00045 CoeffCodingContext::CoeffCodingContext( const TransformUnit& tu, ComponentID component, bool signHide, bool bdpcm )
00046   : m_compID                    (component)
00047   , m_chType                    (toChannelType(m_compID))
00048   , m_width                     (tu.block(m_compID).width)
00049   , m_height                    (tu.block(m_compID).height)
00050   , m_log2CGWidth               ( g_log2SbbSize[ floorLog2(m_width) ][ floorLog2(m_height) ][0] )
00051   , m_log2CGHeight              ( g_log2SbbSize[ floorLog2(m_width) ][ floorLog2(m_height) ][1] )
00052   , m_log2CGSize                (m_log2CGWidth + m_log2CGHeight)
00053   , m_widthInGroups(std::min<unsigned>(JVET_C0024_ZERO_OUT_TH, m_width) >> m_log2CGWidth)
00054   , m_heightInGroups(std::min<unsigned>(JVET_C0024_ZERO_OUT_TH, m_height) >> m_log2CGHeight)
00055   , m_log2BlockWidth            ((unsigned)floorLog2(m_width))
00056   , m_log2BlockHeight           ((unsigned)floorLog2(m_height))
00057   , m_maxNumCoeff               (m_width * m_height)
00058   , m_signHiding                (signHide)
00059   , m_extendedPrecision         (tu.cs->sps->getSpsRangeExtension().getExtendedPrecisionProcessingFlag())
00060   , m_maxLog2TrDynamicRange     (tu.cs->sps->getMaxLog2TrDynamicRange(m_chType))
00061   , m_scanType                  (SCAN_DIAG)
00062   , m_scan                      (g_scanOrder     [SCAN_GROUPED_4x4][m_scanType][gp_sizeIdxInfo->idxFrom(m_width        )][gp_sizeIdxInfo->idxFrom(m_height        )])
00063   , m_scanCG                    (g_scanOrder     [SCAN_UNGROUPED  ][m_scanType][gp_sizeIdxInfo->idxFrom(m_widthInGroups)][gp_sizeIdxInfo->idxFrom(m_heightInGroups)])
00064   , m_CtxSetLastX               (Ctx::LastX[m_chType])
00065   , m_CtxSetLastY               (Ctx::LastY[m_chType])
00066   , m_maxLastPosX(g_uiGroupIdx[std::min<unsigned>(JVET_C0024_ZERO_OUT_TH, m_width) - 1])
00067   , m_maxLastPosY(g_uiGroupIdx[std::min<unsigned>(JVET_C0024_ZERO_OUT_TH, m_height) - 1])
00068   , m_lastOffsetX               (0)
00069   , m_lastOffsetY               (0)
00070   , m_lastShiftX                (0)
00071   , m_lastShiftY                (0)
00072   , m_TrafoBypass               (tu.cs->sps->getSpsRangeExtension().getTransformSkipContextEnabledFlag() && (tu.mtsIdx[m_compID] == MTS_SKIP))
00073   , m_minCoeff                  (-(1 << tu.cs->sps->getMaxLog2TrDynamicRange(m_chType)))
00074   , m_maxCoeff                  ((1 << tu.cs->sps->getMaxLog2TrDynamicRange(m_chType)) - 1)
00075   , m_scanPosLast               (-1)
00076   , m_subSetId                  (-1)
00077   , m_subSetPos                 (-1)
00078   , m_subSetPosX                (-1)
00079   , m_subSetPosY                (-1)
00080   , m_minSubPos                 (-1)
00081   , m_maxSubPos                 (-1)
00082   , m_sigGroupCtxId             (-1)
00083   , m_tmplCpSum1                (-1)
00084   , m_tmplCpDiag                (-1)
00085   , m_sigFlagCtxSet             { Ctx::SigFlag[m_chType], Ctx::SigFlag[m_chType+2], Ctx::SigFlag[m_chType+4] }
00086   , m_parFlagCtxSet             ( Ctx::ParFlag[m_chType] )
00087   , m_gtxFlagCtxSet             { Ctx::GtxFlag[m_chType], Ctx::GtxFlag[m_chType+2] }
00088   , m_sigGroupCtxIdTS           (-1)
00089   , m_tsSigFlagCtxSet           ( Ctx::TsSigFlag )
00090   , m_tsParFlagCtxSet           ( Ctx::TsParFlag )
00091   , m_tsGtxFlagCtxSet           ( Ctx::TsGtxFlag )
00092   , m_tsLrg1FlagCtxSet          (Ctx::TsLrg1Flag)
00093   , m_tsSignFlagCtxSet          (Ctx::TsResidualSign)
00094   , m_sigCoeffGroupFlag         ()
00095   , m_bdpcm                     (bdpcm)
00096 {
00097   // LOGTODO
00098   unsigned log2sizeX = m_log2BlockWidth;
00099   unsigned log2sizeY = m_log2BlockHeight;
00100   if (m_chType == CHANNEL_TYPE_CHROMA)
00101   {
00102     const_cast<int&>(m_lastShiftX) = Clip3( 0, 2, int( m_width  >> 3) );
00103     const_cast<int&>(m_lastShiftY) = Clip3( 0, 2, int( m_height >> 3) );
00104   }
00105   else
00106   {
00107     static const int prefix_ctx[8]  = { 0, 0, 0, 3, 6, 10, 15, 21 };
00108     const_cast<int&>(m_lastOffsetX) = prefix_ctx[ log2sizeX ];
00109     const_cast<int&>(m_lastOffsetY) = prefix_ctx[ log2sizeY ];;
00110     const_cast<int&>(m_lastShiftX)  = (log2sizeX + 1) >> 2;
00111     const_cast<int&>(m_lastShiftY)  = (log2sizeY + 1) >> 2;
00112   }
00113 }
