00115 void CoeffCodingContext::initSubblock( int SubsetId, bool sigGroupFlag )
00116 {
00117   m_subSetId                = SubsetId;
00118   m_subSetPos               = m_scanCG[m_subSetId].idx;
00119   m_subSetPosY              = m_subSetPos / m_widthInGroups;
00120   m_subSetPosX              = m_subSetPos - ( m_subSetPosY * m_widthInGroups );
00121   m_minSubPos               = m_subSetId << m_log2CGSize;
00122   m_maxSubPos               = m_minSubPos + ( 1 << m_log2CGSize ) - 1;
00123   if( sigGroupFlag )
00124   {
00125     m_sigCoeffGroupFlag.set ( m_subSetPos );
00126   }
00127   unsigned  CGPosY    = m_subSetPosY;
00128   unsigned  CGPosX    = m_subSetPosX;
00129   unsigned  sigRight  = unsigned( ( CGPosX + 1 ) < m_widthInGroups  ? m_sigCoeffGroupFlag[ m_subSetPos + 1               ] : false );
00130   unsigned  sigLower  = unsigned( ( CGPosY + 1 ) < m_heightInGroups ? m_sigCoeffGroupFlag[ m_subSetPos + m_widthInGroups ] : false );
00131   m_sigGroupCtxId     = Ctx::SigCoeffGroup[m_chType]( sigRight | sigLower );
00132   unsigned  sigLeft   = unsigned( CGPosX > 0 ? m_sigCoeffGroupFlag[m_subSetPos - 1              ] : false );
00133   unsigned  sigAbove  = unsigned( CGPosY > 0 ? m_sigCoeffGroupFlag[m_subSetPos - m_widthInGroups] : false );
00134   m_sigGroupCtxIdTS   = Ctx::TsSigCoeffGroup( sigLeft  + sigAbove );
00135 }
