00138 unsigned DeriveCtx::CtxModeConsFlag( const CodingStructure& cs, Partitioner& partitioner )
00139 {
00140   assert( partitioner.chType == CHANNEL_TYPE_LUMA );
00141   const Position pos = partitioner.currArea().blocks[partitioner.chType];
00142   const unsigned curSliceIdx = cs.slice->getIndependentSliceIdx();
00143   const unsigned curTileIdx = cs.pps->getTileIdx( partitioner.currArea().lumaPos() );
00144 
00145   const CodingUnit* cuLeft = cs.getCURestricted( pos.offset( -1, 0 ), pos, curSliceIdx, curTileIdx, partitioner.chType );
00146   const CodingUnit* cuAbove = cs.getCURestricted( pos.offset( 0, -1 ), pos, curSliceIdx, curTileIdx, partitioner.chType );
00147 
00148   unsigned ctxId = ((cuAbove && cuAbove->predMode == MODE_INTRA) || (cuLeft && cuLeft->predMode == MODE_INTRA)) ? 1 : 0;
00149   return ctxId;
00150 }
