00153 void DeriveCtx::CtxSplit( const CodingStructure& cs, Partitioner& partitioner, unsigned& ctxSpl, unsigned& ctxQt, unsigned& ctxHv, unsigned& ctxHorBt, unsigned& ctxVerBt, bool* _canSplit /*= nullptr */ )
00154 {
00155   const Position pos         = partitioner.currArea().blocks[partitioner.chType];
00156   const unsigned curSliceIdx = cs.slice->getIndependentSliceIdx();
00157   const unsigned curTileIdx  = cs.pps->getTileIdx( partitioner.currArea().lumaPos() );
00158 
00159   // get left depth
00160   const CodingUnit* cuLeft = cs.getCURestricted( pos.offset( -1, 0 ), pos, curSliceIdx, curTileIdx, partitioner.chType );
00161 
00162   // get above depth
00163   const CodingUnit* cuAbove = cs.getCURestricted( pos.offset( 0, -1 ), pos, curSliceIdx, curTileIdx, partitioner.chType );
00164 
00165   bool canSplit[6];
00166 
00167   if( _canSplit == nullptr )
00168   {
00169     partitioner.canSplit( cs, canSplit[0], canSplit[1], canSplit[2], canSplit[3], canSplit[4], canSplit[5] );
00170   }
00171   else
00172   {
00173     memcpy( canSplit, _canSplit, 6 * sizeof( bool ) );
00174   }
00175 
00177   // CTX do split (0-8)
00179   const unsigned widthCurr  = partitioner.currArea().blocks[partitioner.chType].width;
00180   const unsigned heightCurr = partitioner.currArea().blocks[partitioner.chType].height;
00181 
00182   ctxSpl = 0;
00183 
00184   if( cuLeft )
00185   {
00186     const unsigned heightLeft = cuLeft->blocks[partitioner.chType].height;
00187     ctxSpl += ( heightLeft < heightCurr ? 1 : 0 );
00188   }
00189   if( cuAbove )
00190   {
00191     const unsigned widthAbove = cuAbove->blocks[partitioner.chType].width;
00192     ctxSpl += ( widthAbove < widthCurr ? 1 : 0 );
00193   }
00194 
00195   unsigned numSplit = 0;
00196   if (canSplit[1])
00197   {
00198     numSplit += 2;
00199   }
00200   if (canSplit[2])
00201   {
00202     numSplit += 1;
00203   }
00204   if (canSplit[3])
00205   {
00206     numSplit += 1;
00207   }
00208   if (canSplit[4])
00209   {
00210     numSplit += 1;
00211   }
00212   if (canSplit[5])
00213   {
00214     numSplit += 1;
00215   }
00216 
00217   if (numSplit > 0)
00218   {
00219     numSplit--;
00220   }
00221 
00222   ctxSpl += 3 * ( numSplit >> 1 );
00223 
00225   // CTX is qt split (0-5)
00227   ctxQt =  ( cuLeft  && cuLeft->qtDepth  > partitioner.currQtDepth ) ? 1 : 0;
00228   ctxQt += ( cuAbove && cuAbove->qtDepth > partitioner.currQtDepth ) ? 1 : 0;
00229   ctxQt += partitioner.currQtDepth < 2 ? 0 : 3;
00230 
00232   // CTX is ver split (0-4)
00234   ctxHv = 0;
00235 
00236   const unsigned numHor = ( canSplit[2] ? 1 : 0 ) + ( canSplit[4] ? 1 : 0 );
00237   const unsigned numVer = ( canSplit[3] ? 1 : 0 ) + ( canSplit[5] ? 1 : 0 );
00238 
00239   if( numVer == numHor )
00240   {
00241     const Area& area = partitioner.currArea().blocks[partitioner.chType];
00242 
00243     const unsigned wAbove       = cuAbove ? cuAbove->blocks[partitioner.chType].width  : 1;
00244     const unsigned hLeft        = cuLeft  ? cuLeft ->blocks[partitioner.chType].height : 1;
00245 
00246     const unsigned depAbove     = area.width / wAbove;
00247     const unsigned depLeft      = area.height / hLeft;
00248 
00249     if (depAbove == depLeft || !cuLeft || !cuAbove)
00250     {
00251       ctxHv = 0;
00252     }
00253     else if (depAbove < depLeft)
00254     {
00255       ctxHv = 1;
00256     }
00257     else
00258     {
00259       ctxHv = 2;
00260     }
00261   }
00262   else if( numVer < numHor )
00263   {
00264     ctxHv = 3;
00265   }
00266   else
00267   {
00268     ctxHv = 4;
00269   }
00270 
00272   // CTX is h/v bt (0-3)
00274   ctxHorBt = ( partitioner.currMtDepth <= 1 ? 1 : 0 );
00275   ctxVerBt = ( partitioner.currMtDepth <= 1 ? 3 : 2 );
00276 }
