00278 unsigned DeriveCtx::CtxQtCbf( const ComponentID compID, const bool prevCbf, const int ispIdx )
00279 {
00280   if( ispIdx && isLuma( compID ) )
00281   {
00282     return 2 + (int)prevCbf;
00283   }
00284   if( compID == COMPONENT_Cr )
00285   {
00286     return ( prevCbf ? 1 : 0 );
00287   }
00288   return 0;
00289 }
00290 
00291 unsigned DeriveCtx::CtxInterDir( const PredictionUnit& pu )
00292 {
00293   return ( 7 - ((floorLog2(pu.lumaSize().width) + floorLog2(pu.lumaSize().height) + 1) >> 1) );
00294 }
00295 
00296 unsigned DeriveCtx::CtxAffineFlag( const CodingUnit& cu )
00297 {
00298   const CodingStructure *cs = cu.cs;
00299   unsigned ctxId = 0;
00300 
00301   const CodingUnit *cuLeft = cs->getCURestricted( cu.lumaPos().offset( -1, 0 ), cu, CH_L );
00302   ctxId = ( cuLeft && cuLeft->affine ) ? 1 : 0;
00303 
00304   const CodingUnit *cuAbove = cs->getCURestricted( cu.lumaPos().offset( 0, -1 ), cu, CH_L );
00305   ctxId += ( cuAbove && cuAbove->affine ) ? 1 : 0;
00306 
00307   return ctxId;
00308 }
00309 unsigned DeriveCtx::CtxSkipFlag( const CodingUnit& cu )
00310 {
00311   const CodingStructure *cs = cu.cs;
00312   unsigned ctxId = 0;
00313 
00314   // Get BCBP of left PU
00315   const CodingUnit *cuLeft = cs->getCURestricted( cu.lumaPos().offset( -1, 0 ), cu, CH_L );
00316   ctxId = ( cuLeft && cuLeft->skip ) ? 1 : 0;
00317 
00318   // Get BCBP of above PU
00319   const CodingUnit *cuAbove = cs->getCURestricted( cu.lumaPos().offset( 0, -1 ), cu, CH_L );
00320   ctxId += ( cuAbove && cuAbove->skip ) ? 1 : 0;
00321 
00322   return ctxId;
00323 }
