00326 
00327 unsigned DeriveCtx::CtxPredModeFlag( const CodingUnit& cu )
00328 {
00329   const CodingUnit *cuLeft  = cu.cs->getCURestricted(cu.lumaPos().offset(-1, 0), cu, CH_L);
00330   const CodingUnit *cuAbove = cu.cs->getCURestricted(cu.lumaPos().offset(0, -1), cu, CH_L);
00331 
00332   unsigned ctxId = ((cuAbove && cuAbove->predMode == MODE_INTRA) || (cuLeft && cuLeft->predMode == MODE_INTRA)) ? 1 : 0;
00333 
00334   return ctxId;
00335 }
00336 
00337 unsigned DeriveCtx::CtxIBCFlag(const CodingUnit& cu)
00338 {
00339   const CodingStructure *cs = cu.cs;
00340   unsigned ctxId = 0;
00341   const Position pos = cu.chType == CHANNEL_TYPE_CHROMA ? cu.chromaPos() : cu.lumaPos();
00342   const CodingUnit *cuLeft = cs->getCURestricted(pos.offset(-1, 0), cu, cu.chType);
00343   ctxId += (cuLeft && CU::isIBC(*cuLeft)) ? 1 : 0;
00344 
00345   const CodingUnit *cuAbove = cs->getCURestricted(pos.offset(0, -1), cu, cu.chType);
00346   ctxId += (cuAbove && CU::isIBC(*cuAbove)) ? 1 : 0;
00347   return ctxId;
00348 }
