00350 void MergeCtx::setMergeInfo( PredictionUnit& pu, int candIdx )
00351 {
00352   CHECK( candIdx >= numValidMergeCand, "Merge candidate does not exist" );
00353   pu.regularMergeFlag        = !(pu.ciipFlag || pu.cu->geoFlag);
00354   pu.mergeFlag               = true;
00355   pu.mmvdMergeFlag = false;
00356   pu.interDir                = interDirNeighbours[candIdx];
00357   pu.cu->imv = (!pu.cu->geoFlag && useAltHpelIf[candIdx]) ? IMV_HPEL : 0;
00358   pu.mergeIdx                = candIdx;
00359   pu.mergeType               = mrgTypeNeighbours[candIdx];
00360   pu.mv     [REF_PIC_LIST_0] = mvFieldNeighbours[(candIdx << 1) + 0].mv;
00361   pu.mv     [REF_PIC_LIST_1] = mvFieldNeighbours[(candIdx << 1) + 1].mv;
00362   pu.mvd    [REF_PIC_LIST_0] = Mv();
00363   pu.mvd    [REF_PIC_LIST_1] = Mv();
00364   pu.refIdx [REF_PIC_LIST_0] = mvFieldNeighbours[( candIdx << 1 ) + 0].refIdx;
00365   pu.refIdx [REF_PIC_LIST_1] = mvFieldNeighbours[( candIdx << 1 ) + 1].refIdx;
00366   pu.mvpIdx [REF_PIC_LIST_0] = NOT_VALID;
00367   pu.mvpIdx [REF_PIC_LIST_1] = NOT_VALID;
00368   pu.mvpNum [REF_PIC_LIST_0] = NOT_VALID;
00369   pu.mvpNum [REF_PIC_LIST_1] = NOT_VALID;
00370   if (CU::isIBC(*pu.cu))
00371   {
00372     pu.bv = pu.mv[REF_PIC_LIST_0];
00373     pu.bv.changePrecision(MV_PRECISION_INTERNAL, MV_PRECISION_INT); // used for only integer resolution
00374     pu.cu->imv = pu.cu->imv == IMV_HPEL ? 0 : pu.cu->imv;
00375   }
00376   pu.cu->BcwIdx = ( interDirNeighbours[candIdx] == 3 ) ? BcwIdx[candIdx] : BCW_DEFAULT;
00377 
00378   PU::restrictBiPredMergeCandsOne(pu);
00379   pu.mmvdEncOptMode = 0;
00380 }
00381 void MergeCtx::setMmvdMergeCandiInfo(PredictionUnit& pu, int candIdx)
00382 {
00383   const Slice &slice = *pu.cs->slice;
00384   const int mvShift = MV_FRACTIONAL_BITS_DIFF;
00385   const int refMvdCands[8] = { 1 << mvShift , 2 << mvShift , 4 << mvShift , 8 << mvShift , 16 << mvShift , 32 << mvShift,  64 << mvShift , 128 << mvShift };
00386   int fPosGroup = 0;
00387   int fPosBaseIdx = 0;
00388   int fPosStep = 0;
00389   int tempIdx = 0;
00390   int fPosPosition = 0;
00391   Mv tempMv[2];
00392 
00393   tempIdx = candIdx;
00394   fPosGroup = tempIdx / (MMVD_BASE_MV_NUM * MMVD_MAX_REFINE_NUM);
00395   tempIdx = tempIdx - fPosGroup * (MMVD_BASE_MV_NUM * MMVD_MAX_REFINE_NUM);
00396   fPosBaseIdx = tempIdx / MMVD_MAX_REFINE_NUM;
00397   tempIdx = tempIdx - fPosBaseIdx * (MMVD_MAX_REFINE_NUM);
00398   fPosStep = tempIdx / 4;
00399   fPosPosition = tempIdx - fPosStep * (4);
00400   int offset = refMvdCands[fPosStep];
00401   if ( pu.cu->slice->getPicHeader()->getDisFracMMVD() )
00402   {
00403     offset <<= 2;
00404   }
00405   const int refList0 = mmvdBaseMv[fPosBaseIdx][0].refIdx;
00406   const int refList1 = mmvdBaseMv[fPosBaseIdx][1].refIdx;
00407 
00408   if ((refList0 != -1) && (refList1 != -1))
00409   {
00410     const int poc0 = slice.getRefPOC(REF_PIC_LIST_0, refList0);
00411     const int poc1 = slice.getRefPOC(REF_PIC_LIST_1, refList1);
00412     const int currPoc = slice.getPOC();
00413     if (fPosPosition == 0)
00414     {
00415       tempMv[0] = Mv(offset, 0);
00416     }
00417     else if (fPosPosition == 1)
00418     {
00419       tempMv[0] = Mv(-offset, 0);
00420     }
00421     else if (fPosPosition == 2)
00422     {
00423       tempMv[0] = Mv(0, offset);
00424     }
00425     else
00426     {
00427       tempMv[0] = Mv(0, -offset);
00428     }
00429     if ((poc0 - currPoc) == (poc1 - currPoc))
00430     {
00431       tempMv[1] = tempMv[0];
00432     }
00433     else if (abs(poc1 - currPoc) > abs(poc0 - currPoc))
00434     {
00435       const int scale = PU::getDistScaleFactor(currPoc, poc0, currPoc, poc1);
00436       tempMv[1] = tempMv[0];
00437       const bool isL0RefLongTerm = slice.getRefPic(REF_PIC_LIST_0, refList0)->longTerm;
00438       const bool isL1RefLongTerm = slice.getRefPic(REF_PIC_LIST_1, refList1)->longTerm;
00439       if (isL0RefLongTerm || isL1RefLongTerm)
00440       {
00441         if ((poc1 - currPoc)*(poc0 - currPoc) > 0)
00442         {
00443           tempMv[0] = tempMv[1];
00444         }
00445         else
00446         {
00447           tempMv[0].set(-1 * tempMv[1].getHor(), -1 * tempMv[1].getVer());
00448         }
00449       }
00450       else
00451       tempMv[0] = tempMv[1].scaleMv(scale);
00452     }
00453     else
00454     {
00455       const int scale = PU::getDistScaleFactor(currPoc, poc1, currPoc, poc0);
00456       const bool isL0RefLongTerm = slice.getRefPic(REF_PIC_LIST_0, refList0)->longTerm;
00457       const bool isL1RefLongTerm = slice.getRefPic(REF_PIC_LIST_1, refList1)->longTerm;
00458       if (isL0RefLongTerm || isL1RefLongTerm)
00459       {
00460         if ((poc1 - currPoc)*(poc0 - currPoc) > 0)
00461         {
00462           tempMv[1] = tempMv[0];
00463         }
00464         else
00465         {
00466           tempMv[1].set(-1 * tempMv[0].getHor(), -1 * tempMv[0].getVer());
00467         }
00468       }
00469       else
00470       tempMv[1] = tempMv[0].scaleMv(scale);
00471     }
00472 
00473     pu.interDir = 3;
00474     pu.mv[REF_PIC_LIST_0] = mmvdBaseMv[fPosBaseIdx][0].mv + tempMv[0];
00475     pu.refIdx[REF_PIC_LIST_0] = refList0;
00476     pu.mv[REF_PIC_LIST_1] = mmvdBaseMv[fPosBaseIdx][1].mv + tempMv[1];
00477     pu.refIdx[REF_PIC_LIST_1] = refList1;
00478   }
00479   else if (refList0 != -1)
00480   {
00481     if (fPosPosition == 0)
00482     {
00483       tempMv[0] = Mv(offset, 0);
00484     }
00485     else if (fPosPosition == 1)
00486     {
00487       tempMv[0] = Mv(-offset, 0);
00488     }
00489     else if (fPosPosition == 2)
00490     {
00491       tempMv[0] = Mv(0, offset);
00492     }
00493     else
00494     {
00495       tempMv[0] = Mv(0, -offset);
00496     }
00497     pu.interDir = 1;
00498     pu.mv[REF_PIC_LIST_0] = mmvdBaseMv[fPosBaseIdx][0].mv + tempMv[0];
00499     pu.refIdx[REF_PIC_LIST_0] = refList0;
00500     pu.mv[REF_PIC_LIST_1] = Mv(0, 0);
00501     pu.refIdx[REF_PIC_LIST_1] = -1;
00502   }
00503   else if (refList1 != -1)
00504   {
00505     if (fPosPosition == 0)
00506     {
00507       tempMv[1] = Mv(offset, 0);
00508     }
00509     else if (fPosPosition == 1)
00510     {
00511       tempMv[1] = Mv(-offset, 0);
00512     }
00513     else if (fPosPosition == 2)
00514     {
00515       tempMv[1] = Mv(0, offset);
00516     }
00517     else
00518     {
00519       tempMv[1] = Mv(0, -offset);
00520     }
00521     pu.interDir = 2;
00522     pu.mv[REF_PIC_LIST_0] = Mv(0, 0);
00523     pu.refIdx[REF_PIC_LIST_0] = -1;
00524     pu.mv[REF_PIC_LIST_1] = mmvdBaseMv[fPosBaseIdx][1].mv + tempMv[1];
00525     pu.refIdx[REF_PIC_LIST_1] = refList1;
00526   }
00527 
00528   pu.mmvdMergeFlag = true;
00529   pu.mmvdMergeIdx = candIdx;
00530   pu.mergeFlag = true;
00531   pu.regularMergeFlag = true;
00532   pu.mergeIdx = candIdx;
00533   pu.mergeType = MRG_TYPE_DEFAULT_N;
00534   pu.mvd[REF_PIC_LIST_0] = Mv();
00535   pu.mvd[REF_PIC_LIST_1] = Mv();
00536   pu.mvpIdx[REF_PIC_LIST_0] = NOT_VALID;
00537   pu.mvpIdx[REF_PIC_LIST_1] = NOT_VALID;
00538   pu.mvpNum[REF_PIC_LIST_0] = NOT_VALID;
00539   pu.mvpNum[REF_PIC_LIST_1] = NOT_VALID;
00540   pu.cu->imv = mmvdUseAltHpelIf[fPosBaseIdx] ? IMV_HPEL : 0;
00541 
00542   pu.cu->BcwIdx = (interDirNeighbours[fPosBaseIdx] == 3) ? BcwIdx[fPosBaseIdx] : BCW_DEFAULT;
00543 
00544   for (int refList = 0; refList < 2; refList++)
00545   {
00546     if (pu.refIdx[refList] >= 0)
00547     {
00548       pu.mv[refList].clipToStorageBitDepth();
00549     }
00550   }
00551 
00552 
00553   PU::restrictBiPredMergeCandsOne(pu);
00554 }
00555 
00556 unsigned DeriveCtx::CtxMipFlag( const CodingUnit& cu )
00557 {
00558   const CodingStructure *cs = cu.cs;
00559   unsigned ctxId = 0;
00560 
00561   const CodingUnit *cuLeft = cs->getCURestricted( cu.lumaPos().offset( -1, 0 ), cu, CH_L );
00562   ctxId = (cuLeft && cuLeft->mipFlag) ? 1 : 0;
00563 
00564   const CodingUnit *cuAbove = cs->getCURestricted( cu.lumaPos().offset( 0, -1 ), cu, CH_L );
00565   ctxId += (cuAbove && cuAbove->mipFlag) ? 1 : 0;
00566 
00567   ctxId  = (cu.lwidth() > 2*cu.lheight() || cu.lheight() > 2*cu.lwidth()) ? 3 : ctxId;
00568 
00569   return ctxId;
00570 }
00571 
00572 unsigned DeriveCtx::CtxPltCopyFlag( const unsigned prevRunType, const unsigned dist )
00573 {
00574   uint8_t *ucCtxLut = (prevRunType == PLT_RUN_INDEX) ? g_paletteRunLeftLut : g_paletteRunTopLut;
00575   if ( dist <= RUN_IDX_THRE )
00576   {
00577      return ucCtxLut[dist];
00578   }
00579   else
00580   {
00581     return ucCtxLut[RUN_IDX_THRE];
00582   }
00583 }
